`timescale 1ns / 1ps

// -----------------------------------------------------------------------------
// Behavioral HLS replacement used only for simulation.
//
// The real myproject_0 IP is generated by Vivado HLS.  This stub preserves the
// same port interface, but returns deterministic class scores selected by the
// testbench.  That allows the RTL control path to be tested without requiring
// Vivado, the Basys-3 board, or the large synthesized HLS netlist.
// -----------------------------------------------------------------------------
module myproject_0 (
    input  wire        input_1_V_ap_vld,
    output reg         layer8_out_0_V_ap_vld,
    output reg         layer8_out_1_V_ap_vld,
    output reg         layer8_out_2_V_ap_vld,
    input  wire [10239:0] input_1_V,
    output reg  [23:0] layer8_out_0_V,
    output reg  [23:0] layer8_out_1_V,
    output reg  [23:0] layer8_out_2_V,
    input  wire        ap_clk,
    input  wire        ap_rst,
    input  wire        ap_start,
    output reg         ap_done,
    output reg         ap_ready,
    output reg         ap_idle
);

    // The testbench changes this value to test classes 0, 1, and 2.
    reg [1:0] class_to_return;

    reg       running;
    integer   cycles_remaining;

    always @(posedge ap_clk) begin
        if (ap_rst) begin
            layer8_out_0_V_ap_vld <= 1'b0;
            layer8_out_1_V_ap_vld <= 1'b0;
            layer8_out_2_V_ap_vld <= 1'b0;
            layer8_out_0_V       <= 24'd0;
            layer8_out_1_V       <= 24'd0;
            layer8_out_2_V       <= 24'd0;
            ap_done              <= 1'b0;
            ap_ready             <= 1'b1;
            ap_idle              <= 1'b1;
            running              <= 1'b0;
            cycles_remaining     <= 0;
            class_to_return      <= 2'd0;
        end else begin
            // These signals are pulses/status signals for the controller.
            ap_done              <= 1'b0;
            layer8_out_0_V_ap_vld <= 1'b0;
            layer8_out_1_V_ap_vld <= 1'b0;
            layer8_out_2_V_ap_vld <= 1'b0;

            if (ap_start && !running) begin
                // Accept one frame and wait a few clocks to model inference.
                running          <= 1'b1;
                ap_ready         <= 1'b0;
                ap_idle          <= 1'b0;
                cycles_remaining <= 5;
            end else if (running) begin
                if (cycles_remaining > 1) begin
                    cycles_remaining <= cycles_remaining - 1;
                end else begin
                    // Produce scores with one unambiguous maximum.
                    case (class_to_return)
                        2'd0: begin
                            layer8_out_0_V <= 24'd100;
                            layer8_out_1_V <= 24'd10;
                            layer8_out_2_V <= 24'd1;
                        end
                        2'd1: begin
                            layer8_out_0_V <= 24'd1;
                            layer8_out_1_V <= 24'd100;
                            layer8_out_2_V <= 24'd10;
                        end
                        default: begin
                            layer8_out_0_V <= 24'd1;
                            layer8_out_1_V <= 24'd10;
                            layer8_out_2_V <= 24'd100;
                        end
                    endcase

                    layer8_out_0_V_ap_vld <= 1'b1;
                    layer8_out_1_V_ap_vld <= 1'b1;
                    layer8_out_2_V_ap_vld <= 1'b1;
                    ap_done               <= 1'b1;
                    ap_ready              <= 1'b1;
                    ap_idle               <= 1'b1;
                    running               <= 1'b0;
                    cycles_remaining      <= 0;
                end
            end
        end
    end
endmodule


// -----------------------------------------------------------------------------
// Top-level integration testbench.
//
// This testbench sends three complete 32x32 frames through the same 115200-baud
// UART input used by the host script.  It then receives the one-byte prediction
// emitted by the RTL UART transmitter and checks that the complete control path
// returns the expected class.
// -----------------------------------------------------------------------------
module tb_top_with_hls_stub;

    // The file uses a 1 ns timescale, so these integer delays are nanoseconds.
    localparam integer CLK_PERIOD = 10;      // 100 MHz clock
    localparam integer UART_BIT   = 8681;     // Approx. 115200 baud

    reg        clk;
    reg        rst_btn;
    reg        uart_rx;
    wire       uart_tx;
    wire [6:0] seg;
    wire [3:0] an;

    top dut (
        .clk     (clk),
        .rst_btn (rst_btn),
        .uart_rx (uart_rx),
        .uart_tx (uart_tx),
        .seg     (seg),
        .an      (an)
    );

    // Drive the 100 MHz system clock.
    initial clk = 1'b0;
    always #(CLK_PERIOD / 2) clk = ~clk;

    // Drive one 8N1 UART byte, least-significant data bit first.
    task automatic send_uart_byte;
        input [7:0] value;
        integer bit_number;
        begin
            uart_rx = 1'b0;                 // Start bit
            #(UART_BIT);

            for (bit_number = 0; bit_number < 8; bit_number = bit_number + 1) begin
                uart_rx = value[bit_number];
                #(UART_BIT);
            end

            uart_rx = 1'b1;                 // Stop bit
            #(UART_BIT);
        end
    endtask

    // Send one complete 1024-byte grayscale frame.
    task automatic send_frame;
        integer byte_number;
        begin
            for (byte_number = 0; byte_number < 1024; byte_number = byte_number + 1)
                send_uart_byte(8'h80);
        end
    endtask

    // Receive one 8N1 UART byte from the DUT.
    task automatic receive_uart_byte;
        output [7:0] value;
        integer bit_number;
        begin
            // Wait for the transmitter's start-bit falling edge, then sample
            // each data bit at the center of its bit period.
            @(negedge uart_tx);
            #(UART_BIT + UART_BIT / 2);

            for (bit_number = 0; bit_number < 8; bit_number = bit_number + 1) begin
                value[bit_number] = uart_tx;
                #(UART_BIT);
            end

            // Allow the stop bit and transmitter busy state to finish.
            #(UART_BIT);
        end
    endtask

    task automatic run_class_test;
        input [1:0] expected_class;
        reg [7:0] received_byte;
        begin
            // Select which deterministic score vector the HLS stub returns.
            dut.nn_inst.class_to_return = expected_class;

            send_frame();
            receive_uart_byte(received_byte);

            if (received_byte !== {6'd0, expected_class}) begin
                $display("FAIL: expected class %0d, received byte 0x%02h",
                         expected_class, received_byte);
                $fatal;
            end

            $display("PASS: class %0d returned as UART byte 0x%02h",
                     expected_class, received_byte);
        end
    endtask

    initial begin
        uart_rx = 1'b1;     // UART idle state
        rst_btn = 1'b1;

        repeat (10) @(posedge clk);
        rst_btn = 1'b0;

        // Exercise all three argmax outcomes.
        run_class_test(2'd0);
        run_class_test(2'd1);
        run_class_test(2'd2);

        $display("PASS: top-level UART/frame/controller/argmax integration test");
        $finish;
    end
endmodule
